import java.io.*;import java.util.*;
public class Main{
 static class F{byte[] b=new byte[65536];int p,z;int read()throws Exception{if(p==z){z=System.in.read(b);p=0;if(z<0)return -1;}return b[p++];}int next()throws Exception{int c,v=0;do{c=read();}while(c<=32&&c>=0);while(c>32){v=v*10+c-48;c=read();}return v;}}
 public static void main(String[] args)throws Exception{F in=new F();int t=in.next(),max=0;long[] order=new long[t],answer=new long[t];int[] ms=new int[t];for(int i=0;i<t;i++){int n=in.next();ms[i]=in.next();max=Math.max(max,n);order[i]=((long)n<<20)|i;}Arrays.sort(order);int[] sigma=new int[max+1];for(int d=1;d<=max;d++)for(int j=d;j<=max;j+=d)sigma[j]+=d;int limit=1;for(int v:sigma)limit=Math.max(limit,v);int[] count=new int[limit+1];long[] sum=new long[limit+1];long total=0;int added=0,step=Integer.highestOneBit(limit);for(long key:order){int n=(int)(key>>>20),id=(int)(key&((1<<20)-1));while(added<n){int v=sigma[++added];total+=v;for(int k=v;k<=limit;k+=k&-k){count[k]++;sum[k]+=v;}}int need=n-ms[id],idx=0;long small=0;for(int bit=step;bit>0;bit>>=1){int next=idx+bit;if(next<=limit&&count[next]<=need){need-=count[next];small+=sum[next];idx=next;}}small+=(long)need*(idx+1);answer[id]=total-small;}StringBuilder out=new StringBuilder();for(long a:answer)out.append(a).append('\n');System.out.print(out);}
}